34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
44	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
45	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
46	// (100 * 110) / 100 is exact.
47	const ONE_HUNDRED_PERCENT = 100;
48	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
49	const ADMIN_FEE = 5;
50	const LOYALTY_YEARS = 2;
51	const LOYALTY_DISCOUNT_PERCENT = 20;
52	
53	const applyPercent = (amount: number, percent: number): number =>
54	  (amount * percent) / ONE_HUNDRED_PERCENT;
55	
56	const addSurcharge = (amount: number, surchargePercent: number): number =>
57	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
58	
59	const COMPONENT_TYPES = ["rune", "moonstone"];
60	const BUILDING_BLOCK_SIZE = 3;
61	const BUILDING_BLOCK_BASE_PREMIUM = 60;
62	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
63	
64	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
65	
66	// Risk surcharges are per-item properties of the insured object, each raising
67	// that item's premium by a percentage. They stack multiplicatively: an item
68	// matching two rules is surcharged by the first, then by the second.
69	interface RiskSurcharge {
70	  appliesTo: (item: Item) => boolean;
71	  percent: number;
72	}
73	
74	const RISK_SURCHARGES: RiskSurcharge[] = [
75	  { appliesTo: (item) => item.cursed === true, percent: 50 },
76	  { appliesTo: (item) => (item.enchantment ?? 0) >= 5, percent: 30 },
77	];
78	
79	const riskAdjustedPremiumOf = (item: Item): number =>
80	  RISK_SURCHARGES.reduce(
81	    (premium, surcharge) =>
82	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
83	    basePremiumOf(item),
84	  );
85	
86	const sumRiskAdjustedPremiums = (items: Item[]): number =>
87	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
88	
89	// Alike components are grouped into building blocks of 3, which carry a
90	// special base premium; the remaining components are priced individually,
91	// risk surcharges and all.
92	// Total over the empty group: no components means no blocks and no remainder.
93	const alikeComponentsPremium = (components: Item[]): number => {
94	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
95	  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
96	  return (
97	    blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumRiskAdjustedPremiums(unblocked)
98	  );
99	};
100	
101	const groupByType = (items: Item[]): Item[][] => [
102	  ...items
103	    .reduce(
104	      (groups, item) =>
105	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
106	      new Map<string, Item[]>(),
107	    )
108	    .values(),
109	];
110	
111	// Components and main items are priced by different rules, so each group is
112	// totalled separately: components by building block, main items item by item.
113	const componentsPremium = (components: Item[]): number =>
114	  groupByType(components).reduce(
115	    (total, alike) => total + alikeComponentsPremium(alike),
116	    0,
117	  );
118	
119	// The sum insured is what the items alone are worth to MHPCO, before any
120	// modifier that depends on the customer or the contract they sit in.
121	const sumInsuredOf = (items: Item[]): number =>
122	  sumRiskAdjustedPremiums(items.filter((item) => !isComponent(item))) +
123	  componentsPremium(items.filter(isComponent));
124	
125	// Contract-level modifiers adjust the sum insured by the terms of the deal
126	// rather than the nature of the items: the surcharge on a customer's first
127	// insurance, then the loyalty discount earned by long-standing customers.
128	const contractAdjustedPremiumOf = (
129	  sumInsured: number,
130	  customer: Customer,
131	): number => {
132	  const afterFirstInsurance = addSurcharge(
133	    sumInsured,
134	    FIRST_INSURANCE_SURCHARGE_PERCENT,
135	  );
136	  return customer.yearsWithMHPCO >= LOYALTY_YEARS
137	    ? applyPercent(afterFirstInsurance, ONE_HUNDRED_PERCENT - LOYALTY_DISCOUNT_PERCENT)
138	    : afterFirstInsurance;
139	};
140	
141	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
142	// so that no percentage ever applies to it.
143	const billableFrom = (premium: number): number =>
144	  Math.ceil(premium) + ADMIN_FEE;
145	
146	const quote = (step: QuoteStep, customer: Customer): QuoteResult => ({
147	  premium: billableFrom(
148	    contractAdjustedPremiumOf(sumInsuredOf(step.items), customer),
149	  ),
150	});
151	
152	export const runScenario = (scenario: Scenario): ScenarioResult => ({
153	  results: scenario.steps.map((step) => quote(step, scenario.customer)),
154	});
